All loop directions retain Gaussian suppression precisely when
$\operatorname{rank}M=c+L$. At that rank, writing $m=c+L$, one has
\begin{equation}
 K_0(t)=(2\pi)^{-2m}B_M(t)^{-2}.
 \label{eq:physical-uv-retained-delta}
\end{equation}
If the rank is smaller, $K_0(t)=\infty$. For full row rank suppose
the remaining positive weight on $(0,1]^n$ is bounded above and
below by constant multiples of
$\prod_e t_e^{\beta_e-1}\,\mathrm dt_e$. This weight includes the
remaining vacuum and boundary densities of the coefficient under
test. For $S\subseteq\{1,\ldots,n\}$ put
\[
 \begin{aligned}
 d_S&=m-\operatorname{rank}M_{S^c},\\
 a_S&=\operatorname{rank}M_{S^c}-\operatorname{rank}C_{S^c},
 \end{aligned}
\]
with the subscripts retaining columns. The integrated $K_h$ is
finite if and only if every nonempty $S$ satisfies
\begin{equation}
 \sum_{e\in S}\beta_e>2d_S+h\,\mathbf 1_{\{a_S<L\}} .
 \label{eq:physical-uv-retained-faces}
\end{equation}
An upper bound by the stated weight suffices for convergence under
these inequalities.

In background Feynman gauge the complete root-pair contribution to
the bare one-loop background action, per unit four-volume on the
UV proper-time interval $\varepsilon<t<T$, satisfies
\begin{equation}
 [B^2]\bigl(\Gamma^{(1)}(B)-\Gamma^{(1)}(0)\bigr)
 =-\frac{7}{2(4\pi)^2}
 \int_\varepsilon^T e^{-tv^2}\frac{\dd t}{t}.
 \label{eq:uvpeC-root-response}
\end{equation}
The divergence persists for any fixed $v$ even after the normal
polarization and Faddeev--Popov ghost have been included.

Fix $w>0$. Uniformly in $R\ge1$, $q$ as above and all allowed $h$,
as $m\to\infty$,
\begin{equation}
 \begin{aligned}
 H_{R,h}(q)&=-\frac{4e^2 w h_j^2}{M}K_R(h_j e_j)+O_w(e^2 M^{-2}),\\
 K_R(x)&=\int_0^\infty t e^{-t}
    \sum_{n\in\mathbb Z^4}
    \frac{e^{-|x+2\pi R n|^2/(4t)}}{(4\pi t)^2}\,\dd t .
 \end{aligned}
 \label{eq:s6Wilson-soft}
\end{equation}
For sufficiently large $m$ and $e\ne0$, the order-$e^2$ transverse
boundary correction per unit volume stays strictly negative and
bounded away from zero along $q=1/R\to0$, including the stipulated
common history integration.

Let $L\ge0$ be self-adjoint, let $C_0$ be bounded and positive, and
let $P_r=e^{-r h_M(L)}$, $r>0$. Then
\begin{equation}
 P_rC_0P_r=P_r^2C_0
 \quad\Longleftrightarrow\quad [C_0,P_r]=0.
\label{eq:update-commuting-transfer}
\end{equation}
This is equivalent to commutation of $C_0$ with the spectral
projections of $L$. Without it the exact remainder is
$P_r[C_0,P_r]$.

For centered fields on a common real smeared-field domain with finite
second moments, the three blocks in \eqref{eq:update-three-source-blocks} imply
$\psi_{\bb}(f)=\chi_{\bb}(P_r^*f)$ almost surely for each test at fixed $r$.
For a shared random depth, put
$v_f(r)=\langle f,P_rC_0P_r^*f\rangle_{E,\bb}$.
If $v_f^2$ is integrable, the centered conditional Gaussian model has
\begin{equation}
 \langle\psi_{\bb}(f)^4\rangle_{0,c}
      =3\operatorname{Var}_{\mathsf w}(v_f).
\label{eq:update-depth-fourth-cumulant}
\end{equation}
Under the same square-integrability hypothesis, if its conditional
translation-invariant correlations $c_r(R)=\mathbb E_r[\psi_{\bb}(f)\psi_{\bb}(f_R)]$ tend to zero, then
\begin{equation}
 \lim_{\|R\|\to\infty}
 \operatorname{Cov}_{\mathsf w}(\psi_{\bb}(f)^2,\psi_{\bb}(f_R)^2)
      =\operatorname{Var}_{\mathsf w}(v_f).
\label{eq:update-depth-cluster}
\end{equation}

For scalar carrier coefficients define
\begin{equation}
 \norm{A}_{\chi}:=\max_{\kappa=\pm1}|\chi_\kappa(A)|.
 \label{eq:character-norm}
\end{equation}
This is a submultiplicative norm. Let \(\nu_{\bb}\) be a positive
integration measure. If a measurable complete graph integrand is
\(g(\xi)=\sum_\kappa\mathsf P_\kappa g_\kappa(\xi)\)
and \(|g_\kappa(\xi)|\leq M_\kappa(\xi)\), with
\(M_\pm\in L^1(\dd\nu_{\bb})\), then
\begin{equation}
\begin{aligned}
 \int\norm{g(\xi)}_\chi\dd\nu_{\bb}
 &\leq\int(M_++M_-)\dd\nu_{\bb}<\infty,\\
 \int g\,\dd\nu_{\bb}
 &=\sum_\kappa\mathsf P_\kappa\int g_\kappa\,\dd\nu_{\bb}.
\end{aligned}
 \label{eq:character-integral-majorant}
\end{equation}
The same statement holds uniformly in external parameters whenever
the two majorants are uniform. For matrix coefficients replace the
absolute value by a fixed submultiplicative matrix norm.

Fix the finite routing and compact real external set of
\eqref{eq:routing}. Choose $S$ with $|S|=L$ and invertible $C_S$, and
write $\ell_j=q_j$ for $j\in S$. On selected line $j$, take the actual
nonnegative comparison factor
\begin{equation}
 C_j^{\Ph}(\ell_j)
  :=\frac{\Ph_j(a_j^2|\ell_j|^2)}{|\ell_j|^2+m_j^2},
 \qquad a_j>0,\quad m_j\geq0,
 \label{eq:optimized-selected-factor}
\end{equation}
with a finite positive representing measure $\rho_{j,\bb}$.
Assume the \emph{complete product} of the numerator and all
unselected virtual-line factors, expressed in these variables, obeys
\begin{equation}
 \left|N_G(k(\ell,p),p)\prod_{i\notin S} C_i^{\rm full}(q_i)\right|
 \leq\sum_{\alpha\in\mathcal A}c_\alpha
       \prod_{j\in S}(1+|\ell_j|^{d_{j\alpha}}),
 \label{eq:anisotropic-complete-envelope}
\end{equation}
uniformly in $p\in\mathcal K$, with $\mathcal A$ finite,
$c_\alpha\geq0$ and $d_{j\alpha}\geq0$. Thus an unselected
massless denominator must be controlled as part of the \emph{full}
envelope; it is not assumed bounded merely because its multiplier is.
Set $d_j=\max_\alpha d_{j\alpha}$ and suppose
\begin{equation}
 \rho_{j,\bb}(\{0\})=0,\qquad
 M_{1+d_j/2}[\rho_{j,\bb}]<\infty\quad(j\in S).
 \label{eq:optimized-moment-budget}
\end{equation}
Then the specified complete graph is absolutely convergent,
uniformly over $\mathcal K$, including mixed soft and UV regions
in the selected variables. The following one-line integral does
\emph{not} include the Fourier factor $(2\pi)^{-4}$:
\begin{equation}
 \begin{aligned}
 Q_{d,j}(m_j)
  &:=\int_{\RR^4}\frac{|q|^d\Ph_j(a_j^2|q|^2)}{q^2+m_j^2}
         \dd^4q_{\bb}\\
  &\leq\pi^2\Gamma(1+d/2)a_j^{-2-d}
          M_{1+d/2}[\rho_{j,\bb}].
 \end{aligned}
 \label{eq:optimized-one-line-moment}
\end{equation}
For $m_j=0$ this is an equality, possibly infinite. For each fixed
$m_j\ge0$ the one-line integral is finite exactly when the heat
measure has no atom at zero and the indicated inverse moment is
finite. This exact one-line threshold gives a sufficient condition
for the complete graph under \eqref{eq:anisotropic-complete-envelope}.

Under Theorem~\ref{thm:optimized-selected-lines}, if for some
$\delta>0$ the moments
$M_{1+(d_j+\delta)/2}[\rho_{j,\bb}]$ are finite, then
\begin{equation}
 \begin{aligned}
 &\int_{|q|>R}\frac{|q|^d\Ph_j(a_j^2|q|^2)}{q^2+m_j^2}
  \dd^4q_{\bb}\\
 &\quad\leq \frac{\pi^2\Gamma(1+(d+\delta)/2)}
                       {R^\delta a_j^{2+d+\delta}}
       M_{1+(d+\delta)/2}[\rho_{j,\bb}],
 \quad 0\leq d\leq d_j.
 \end{aligned}
 \label{eq:optimized-tail-bound}
\end{equation}
Replacing one factor at a time in
\eqref{eq:anisotropic-integrated-bound} and taking the union over
$\{|\ell_j|>R\}$ gives an $O(R^{-\delta})$ tail for the complete
specified graph in the selected variables.

In \eqref{eq:two-loop-selected-example}, interpret the third
factor as the analytic denominator
$[(k_1-k_2+p)^2+1]^{-1}$ for complex $p$, with
$q^2=\sum_{\mu=1}^4q_\mu^2$. Denote this complex integral by
$\mathcal B_{\rm ex}(p)$. It is holomorphic on the tube
$\mathcal T_1=\{p=x+\ii y\in\CC^4:|y|<1\}$, and
\begin{equation}
 |\mathcal B_{\rm ex}(x+\ii y)|
 \leq\frac{1}{768\pi^4(1-|y|^2)}.
 \label{eq:two-loop-complex-bound}
\end{equation}
For every real $p_0$, $0<r<1/2$, and multi-index
$\alpha\in\mathbb N_0^4$, its external derivatives satisfy
\begin{equation}
 |\partial_p^\alpha\mathcal B_{\rm ex}(p_0)|
 \leq\frac{\alpha!\,r^{-|\alpha|}}
 {768\pi^4(1-4r^2)}.
 \label{eq:two-loop-complex-derivative}
\end{equation}
For real external momenta $p,p'\in\RR^4$ one also has the
global stability estimate
\begin{equation}
 \begin{aligned}
 \norm{\nabla_p\mathcal A_{\rm ex}(p)}
 &\leq\frac{9}{8\sqrt3}\,\frac1{768\pi^4},\\
 |\mathcal A_{\rm ex}(p)-\mathcal A_{\rm ex}(p')|
 &\leq\frac{9}{6144\sqrt3\,\pi^4}\norm{p-p'}.
 \end{aligned}
 \label{eq:two-loop-real-Lipschitz}
\end{equation}
For real $p$, $\mathcal B_{\rm ex}(p)=\mathcal A_{\rm ex}(p)$.
The gradient is also globally Lipschitz. For $p,p',h\in\RR^4$,
\begin{equation}
 \begin{aligned}
 &\norm{\nabla\mathcal A_{\rm ex}(p)
             -\nabla\mathcal A_{\rm ex}(p')}\leq
             \frac{\norm{p-p'}}{384\pi^4},\\
 &|\mathcal A_{\rm ex}(p+h)-\mathcal A_{\rm ex}(p)
        -\nabla\mathcal A_{\rm ex}(p)\cdot h|\leq
             \frac{\norm{h}^2}{768\pi^4}.
 \end{aligned}
 \label{eq:two-loop-real-second-order}
\end{equation}
These are coefficient-level real and complex stability bounds, not
assertions about Lorentzian cuts or scattering amplitudes. The tube
can be checked explicitly here because all external dependence
resides in the massive third denominator under the selected routing.

Fix a finite routing with $L\ge1$ and a set $S$ of $L$ independent
rows, as in Theorem~\ref{thm:optimized-selected-lines}. Let
$\boldsymbol\varrho_{G,\bb}(\dd\boldsymbol\lambda)$ be a finite positive
measure on $[0,\infty)^I$, not necessarily a product. The parameters
$\lambda_i$ have inverse-momentum-squared units and include the
line-depth scale. Assume $\lambda_j>0$ almost everywhere for $j\in S$.
Conditional on these parameters, write the graph with its selected
factors
\[
 \frac{e^{-\lambda_j|\ell_j|^2}}{\ell_j^2+m_j^2},
 \qquad \ell_j=q_j,\quad m_j\ge0.
\]
Let $\mathcal R_G(k,p;\boldsymbol\lambda)$ denote the entire remaining
coefficient, including unselected lines, vertices, sources, and contacts.
The joint absolute comparison integral is
\begin{equation}
\begin{aligned}
 \mathcal A_G^{\rm joint}(p)
   &:=\int\boldsymbol\varrho_{G,\bb}(\dd\boldsymbol\lambda)
       \int\frac{\dd^{4L}k_{\bb}}{(2\pi)^{4L}}\,
          |\mathcal R_G(k,p;\boldsymbol\lambda)|\\
   &\hspace{10mm}\times\prod_{j\in S}
       \frac{e^{-\lambda_j|q_j|^2}}{q_j^2+m_j^2}.
\end{aligned}
\label{eq:update-joint-graph-integral}
\end{equation}
Assume $\mathcal R_G$ obeys the complete envelope
\eqref{eq:anisotropic-complete-envelope} uniformly in the joint
parameters and external data. Unselected heat factors may be discarded
only through $e^{-\lambda_i q_i^2}\le1$; unselected massless
singularities still need that envelope. Define
\begin{equation}
\begin{aligned}
 b_d(\lambda)&:=\pi^2\Gamma(1+d/2)\lambda^{-1-d/2},\\
 \mathcal M_{G,S}
  &:=\sum_{\alpha\in\mathcal A}c_\alpha
    \int\boldsymbol\varrho_{G,\bb}(\dd\boldsymbol\lambda)
       \prod_{j\in S}
       [b_0(\lambda_j)+b_{d_{j\alpha}}(\lambda_j)].
\end{aligned}
\label{eq:update-joint-moment-budget}
\end{equation}
If $\mathcal M_{G,S}<\infty$, the joint absolute graph integral is
uniformly finite and is bounded by
\begin{equation}
 \sup_{p\in\mathcal K}\mathcal A_G^{\rm joint}(p)
 \le\frac{|\det C_S|^{-4}}{(2\pi)^{4L}}\mathcal M_{G,S}.
\label{eq:update-joint-graph-bound}
\end{equation}
This justifies the exchanges of loop and joint heat/depth
integrations for that graph.

For positive exponents $u_j$ on any finite selected set,
\begin{equation}
 \int\prod_{j\in S}\lambda_j^{-u_j}
           \boldsymbol\varrho_{G,\bb}(\dd\boldsymbol\lambda)
  =\prod_{j\in S}\frac{\Gamma(u_j+\tfrac12)}{\sqrt\pi}
       \int\mathsf w_{\bb}(\dd r_{\bb})\,r^{-2\sum_{j\in S}u_j}.
\label{eq:update-joint-inverse-lapse}
\end{equation}
Both sides are understood as nonnegative extended integrals for a
probability law supported on strictly positive depths. Under a uniform
complete envelope, a sufficient shared-depth condition for
Theorem~\ref{thm:update-joint-heat} is
\begin{equation}
 \begin{gathered}
 \mathsf w_{\bb}(\{0\})=0,\qquad
 \int_{(0,r_{\rm ref}]}r^{-R_G}\mathsf w_{\bb}(\dd r_{\bb})<\infty,\\
 R_G=2L+\max_{\alpha\in\mathcal A}\sum_{j\in S}d_{j\alpha}.
 \end{gathered}
\label{eq:update-depth-budget}
\end{equation}
with arbitrary fixed $r_{\rm ref}>0$. This reference only separates
the small-depth region; it is not a new physical scale.

For \eqref{eq:update-selector-law}, every real depth moment exists, and
\begin{equation}
\begin{aligned}
 Z_\vartheta&=2(B_*/A_*)^{\vartheta/2}
                  K_\vartheta(2\sqrt{A_*B_*}),\\
 \mathbb E r^u&=(B_*/A_*)^{u/2}
       \frac{K_{\vartheta+u}(2\sqrt{A_*B_*})}
            {K_\vartheta(2\sqrt{A_*B_*})},\\
 \mathcal F_\vartheta(\omega)&:=\mathbb E e^{-\omega r}\\
  &=\left(\frac{A_*}{A_*+\omega}\right)^{\vartheta/2}
       \frac{K_\vartheta(2\sqrt{B_*(A_*+\omega)})}
            {K_\vartheta(2\sqrt{A_*B_*})},\quad\omega\ge0.
\end{aligned}
\label{eq:update-selector-transform}
\end{equation}
If $B_*=0$ instead, normalization requires $\vartheta>0$, and
$\mathbb E r^{-u}<\infty$ holds exactly for $u<\vartheta$.

For fixed positive selector coefficients and real $\vartheta$, put
\[
 C_\vartheta=\frac{\sqrt\pi B_*^{\vartheta/2-1/4}}{Z_\vartheta}.
\]
Then
\begin{equation}
 \mathcal F_\vartheta(\omega)
 \sim C_\vartheta(A_*+\omega)^{-\vartheta/2-1/4}
       e^{-2\sqrt{B_*(A_*+\omega)}}.
\label{eq:update-depth-transform-tail}
\end{equation}
At fixed $M\ge0$ the marginal internal multiplier consequently obeys
\begin{equation}
\begin{aligned}
 \overline\Phi_\vartheta(x)
   &:=\mathcal F_\vartheta(2h_M(x))\\
   &\sim C_\vartheta2^{-\vartheta/2-1/4}
       x^{-\vartheta/4-1/8}e^{-2\sqrt{2B_*}\,x^{1/4}}.
\end{aligned}
\label{eq:update-selector-uv-tail}
\end{equation}
An exact equality $\int\mathsf w_{\bb}(\dd r_{\bb})e^{-2rh_M(x)}
=e^{-a h_M(x)}$ for every $x\ge0$ instead forces
$\mathsf w_{\bb}=\delta^{\rm depth}_{\bb,a/2}$.

The normalized measure and kernel
\begin{equation}
 \rho_{\bb}=\sum_{n=1}^\infty2^{-n}\delta^{\rm heat}_{\bb,n},\qquad
 \Ph(z)=\frac1{2e^z-1}
 \label{eq:meromorphic-counterexample}
\end{equation}
satisfy the gap condition with \(\tau_*=1\), but their complex
continuation has poles away from the negative real axis.

For \(t>0\) and \(\omega>0\), the following Euclidean GT-coordinate covariance
fails reflection positivity:
\begin{equation}
 C_t(u)=\int_{\RR}\frac{\dd p_{\bb}}{2\pi}\,
       \frac{e^{\ii pu}e^{-tp^2}}{p^2+\omega^2}
 \label{eq:heat-time-covariance}
\end{equation}

The function \eqref{eq:update-cross-family} has an ordinary real signed
spectral measure with finite weighted total variation precisely when
$m\le M$, or when $m>M$ and
$\sin(a\sqrt{m^2-M^2})=0$. In these cases
\begin{equation}
\begin{aligned}
 \nu_{c,\bb}(\dd s_{\rm sp})
   &=c_*\delta^{\rm sp}_{\bb,m^2}(\dd s_{\rm sp})
                      +h(s_{\rm sp})\dd s_{{\rm sp},\bb},\\
 c_*&=\begin{cases}
 e^{a(M-\sqrt{M^2-m^2})},&m\le M,\\
 e^{aM}\cos(a\sqrt{m^2-M^2}),&m>M,
 \end{cases}\\
 h(s_{\rm sp})&=
 \frac{e^{aM}\sin(a\sqrt{s_{\rm sp}-M^2})}{\pi(m^2-s_{\rm sp})}
                    \mathbf1_{s_{\rm sp}>M^2}.
\end{aligned}
\label{eq:update-cross-measure}
\end{equation}
At an admitted embedded pole the density has its removable value.
At $m=M$ it behaves as
$-ae^{aM}/(\pi\sqrt{s_{\rm sp}-M^2})$, with a separate threshold
atom of weight $e^{aM}$. The total-variation transform satisfies
\begin{equation}
 D_c(x)=\frac{2e^{aM}}{\pi^2}\frac{\log(a^2x)}{x}+O(x^{-1})
       \quad(x\to\infty).
\label{eq:update-cross-cost-tail}
\end{equation}

For any positive two-channel spectral completion of an admitted
\eqref{eq:update-cross-family}, the four-dimensional integral
\begin{equation}
 \int_{\RR^4}\dd^4Q_{E,\bb}\,
       C_{11}(|Q_E|^2)C_{22}(|Q_E+P_E|^2)
\label{eq:update-completed-bubble}
\end{equation}
is ultraviolet divergent for fixed $P_E$.

Assume $0<m_b^2<M^2$ in \eqref{eq:update-positive-bulk}, and let
$r_i\ge0$ label finitely many sampled layers, including the boundary
$r_b=0$. Define
\begin{equation}
\begin{aligned}
 \kappa_*&=\frac{\sqrt{\beta^2+4(M^2-m_b^2)}-\beta}{2},\\
 s_*&=M^2-\kappa_*^2,\qquad
 Z_*=(1+\beta/(2\kappa_*))^{-1},\qquad h_i=e^{-r_i\kappa_*},\\
 k_n&=\sqrt{s_{\rm sp}-M^2},\qquad t_s=m_b^2-s_{\rm sp},\\
 f_i(s_{\rm sp})&=\cos(k_n r_i)+\frac{t_s}{\beta k_n}\sin(k_n r_i),\\
 \rho_{b,\bb}(s_{\rm sp})&=\frac{\beta k_n}{\pi(t_s^2+\beta^2 k_n^2)}.
\end{aligned}
\label{eq:update-positive-spectrum-data}
\end{equation}
On the admitted layer-source forms the positive matrix measure
\begin{equation}
\begin{aligned}
 \nu_{ij,\bb}(\dd s_{\rm sp})
   ={}&Z_*h_i h_j\delta^{\rm sp}_{\bb,s_*}(\dd s_{\rm sp})\\
     &+\rho_{b,\bb}(s_{\rm sp})f_i(s_{\rm sp})f_j(s_{\rm sp})
         \mathbf1_{s_{\rm sp}>M^2}\dd s_{{\rm sp},\bb}
\end{aligned}
\label{eq:update-positive-spectrum}
\end{equation}
represents every block in \eqref{eq:update-positive-bulk-blocks}.
The boundary weights satisfy $Z_*+\int_{M^2}^\infty\rho_{b,\bb}(s_{\rm sp})\dd s_{{\rm sp},\bb}=1$.

Suppose an actual Lorentzian smeared operator is defined by
$\psi_{\bb}(x)=\int\dd\mu_{\bb}(u)K_{\bb}(x,u)\chi_{\bb}(u)$ on an admitted
common domain. For a real scalar kernel, the difference between its
ordered covariance and transferring the already ordered covariance is
\begin{equation}
\begin{aligned}
 &\langle X_\gamma^+\{\psi_{\bb}(x)\psi_{\bb}(y)\}\rangle
          -(K\otimes K)G^{++}_{\chi_{\bb}}(x,y)\\
 &=\int\dd\mu_{\bb}(u)\dd\mu_{\bb}(v)\,
       K_{\bb}(x,u)K_{\bb}(y,v)\\
 &\quad\times[\theta(\gamma_x-\gamma_y)-\theta(\gamma_u-\gamma_v)]
                       \langle[\chi_{\bb}(u),\chi_{\bb}(v)]\rangle.
\end{aligned}
\label{eq:update-GT-ordering-correction}
\end{equation}

Let $u_y(r)$ be the minimizing transfer and let
$\Lambda(y)=-a(0)u_y'(0)$ be its boundary flux. With $G_y^D$ the
Dirichlet Green function of the mode operator, one has
\begin{equation}
 \begin{aligned}
 \partial_y\Lambda(y)&=\int_0^\infty b_{\parallel}(s)u_y(s)^2\,\mathrm ds,\\
 -\partial_yu_y(r)&=\int_0^\infty
      G_y^D(r,s)b_{\parallel}(s)u_y(s)\,\mathrm ds .
 \end{aligned}
 \label{eq:closure-native-flux-uv}
\end{equation}
An interior readout at any $r>0$ is independent of carrier frequency
exactly when $b_{\parallel}$ vanishes throughout the connected ray.

The bottom $E_*$ of the charged spectrum is strictly positive for
every real $e$. In the neutral vacuum the transverse magnetic
two-point function has a positive one-photon atom with laboratory
energy $r$ at each fixed $\mathbf k\ne0$. In the charged sector,
take the probe that prepares the prescribed Gauss field and the
transverse Fock vacuum $|0\rangle$. For $eu\ne0$ its energy law is
absolutely continuous on $[E_*,\infty)$. With $x=E-E_*\downarrow0$
its density is asymptotic to $C x^{\alpha-1}/\Gamma(\alpha)$,
where
\begin{equation}
\begin{aligned}
 E_*&= E_{\rm c}+\frac{e^2}{8\pi^2a}
       (1-u^2)\frac{\operatorname{arctanh}u}{u},\\
 w(\mathbf n)&=\frac{e^2}{2(2\pi)^3}
       \frac{u^2-(\mathbf v\cdot\mathbf n)^2}{d^2},\\
 \alpha&=\int_{S^2} w\,\mathrm d\Omega
  =\frac{e^2}{2\pi^2}
       \left(\frac{\operatorname{arctanh}u}{u}-1\right),\\
 C&=(2a)^\alpha\exp\!\left[-\int_{S^2} w\log d\,\mathrm d\Omega\right].
\end{aligned}
\label{eq:uv-rigid-edge-constants}
\end{equation}
At $u=0$ use $\operatorname{arctanh}(u)/u=1$.
If $eu=0$, this probe gives a unit atom at $E_*$. In either case
neutral photons of arbitrarily small positive energy are available.

For \(m>0\) and \(t>0\), on
\(\CC\setminus[4m^2,\infty)\),
\begin{equation}
 b_t(\sMand)=b_{\rm std}(\sMand)+R_t(\sMand),
 \label{eq:bubble-entire-decomposition}
\end{equation}
where the remainder is entire and has the representation
\begin{equation}
 R_t(\sMand)
 =\frac1{16\pi^2}\int_0^1\dd x
   \int_0^{W_{\min}(x)}\frac{\dd W}{W}\,
       e^{-m^2W}\bigl[1-e^{Wx(1-x)\sMand}\bigr].
 \label{eq:entire-bubble-remainder}
\end{equation}
It vanishes at zero, is real on the real axis, and satisfies
\begin{equation}
 |R_t(\sMand)|
   \leq\frac{3t|\sMand|}{64\pi^2}e^{t|\sMand|}.
 \label{eq:entire-remainder-bound}
\end{equation}
Thus \(b_t\to b_{\rm std}\) uniformly on compact subsets of the
cut plane as \(t\downarrow0\).

For real \(s>0\), the entire remainder of
Proposition~\ref{prop:entire-bubble-remainder} satisfies
\begin{equation}
 -R_t(s)\geq
 \frac{\log2}{48\pi^2}e^{-2tm^2}
       \left(e^{2ts/9}-1\right).
 \label{eq:Gaussian-remainder-growth-lower}
\end{equation}
Thus no addition of a finite polynomial makes \(R_t\), or the
normalized bubble boundary \(b_t\), polynomially bounded along
the positive real axis at fixed \(t>0\).

The function \(B_{a,m}\) is finite for all real \(P\) and is
\(C^5\). It is not \(C^6\) at \(P=0\); in particular, no
function holomorphic in \(P^2\) on a neighbourhood of zero can
restrict to this bubble there. Its coordinate covariance has the
positive large-distance tail
\begin{equation}
 \mathcal C_{a,m}(x)=
   \frac{3a}{4\pi^2m^2}|x|^{-5}+O(|x|^{-6}).
 \label{eq:stable-covariance-long-tail}
\end{equation}
For $b(h)=B_{a,m}(h e_1)$ and real $h\to0$, the first nonanalytic
term is
\begin{equation}
 \begin{aligned}
 b(h)={}&b(0)+\frac{b''(0)}{2}h^2+\frac{b^{(4)}(0)}{24}h^4\\
        &-\frac{a^2}{8192\pi^2m^4}h^6\log\frac{m}{|h|}
          +O(h^6).
 \end{aligned}
 \label{eq:stable-bubble-leading-log}
\end{equation}

Let \(F(u)=\Ph(a^2u)\) for a nonzero finite positive completely
monotone law, let \(m\geq0\), and assume
\begin{equation}
 \mathcal Q_F:=\int_0^\infty F(u)^2\dd u<\infty.
 \label{eq:QED-Ltwo-condition}
\end{equation}
Then \eqref{eq:bare-QED-loop} is absolutely convergent for every
real \(Q\), is continuous in \(Q\), and obeys
\begin{equation}
\begin{aligned}
 \Pi_{\rm bv}^{\mu\nu}(0)&=\kappa_F\delta^{\mu\nu},\\
 Q_\mu\Pi_{\rm bv}^{\mu\nu}(Q)
      &=\kappa_F Q^\nu+o(|Q|),\\
 \kappa_F
 &=\frac{e^2}{8\pi^2}\int_0^\infty
     \frac{u(u+2m^2)}{(u+m^2)^2}F(u)^2\dd u.
\end{aligned}
 \label{eq:general-Ward-obstruction}
\end{equation}
Here \(\kappa_F>0\) when \(e\ne0\).
For \(m=0\), the rational factor in the integral is one for
\(u>0\). Conversely, absolute convergence of the original
nontrivial tensor at any fixed real \(Q\) implies
\eqref{eq:QED-Ltwo-condition}, by the radial-tail argument in
Lemma~\ref{lem:Ward-common-cutoff}. No differentiability at
\(u=0\) is assumed.

Let \(S_\Ph^{-1}(p)=F(p^2)^{-1}(\ii\slashed p+m)\),
with \(F>0\), \(F(0)>0\), \(m\geq0\), and Hermitian Euclidean
gamma matrices. Write \(A_R=F(R^2)^{-1}\), \(A_0=F(0)^{-1}\).
Any vertex satisfying \eqref{eq:dressed-WTI} obeys the exact identity
\begin{equation}
 \left\|n_\mu\Gamma_\Ph^\mu(Rn,0)\right\|^2
       =A_R^2+\frac{m^2}{R^2}(A_R-A_0)^2,
 \label{eq:Ward-vertex-exact-norm}
\end{equation}
for a unit vector \(n\) and \(R>0\). In particular,
\begin{equation}
 \left\|n_\mu\Gamma_\Ph^\mu(Rn,0)\right\|
 \geq\frac1R\left[
       \frac{\sqrt{R^2+m^2}}{F(R^2)}-\frac{m}{F(0)}
                      \right].
 \label{eq:Ward-vertex-growth-lower}
\end{equation}
The norm is the matrix operator norm. For a superpolynomially
decreasing \(F(R^2)\), no globally polynomially bounded vertex
can satisfy this identity in the stated auxiliary field coordinates.

The dimensionless Laplace measure of \(\Ph_\mu\) is the probability
measure
\begin{equation}
 \rho_{\mu,\bb}(\dd\tau)=\frac{e^\mu}{2\sqrt\pi}\,
 \tau^{-3/2}\exp\!\left(-\mu^2\tau-\frac1{4\tau}\right)\dd\tau.
\label{eq:OQED-dimensionless-measure}
\end{equation}
It has no atom at zero and no positive support gap, including when
\(\mu>0\). Every inverse moment is finite. For \(r>0\),
\begin{equation}
 M_r[\rho_{\mu,\bb}]=
 \begin{cases}
 \displaystyle\frac{e^\mu}{\sqrt\pi}(2\mu)^{r+1/2}
                      K_{r+1/2}(\mu),&\mu>0,\\[2pt]
 \displaystyle\frac{4^r\Gamma(r+1/2)}{\sqrt\pi},&\mu=0.
 \end{cases}
\label{eq:OQED-inverse-moments}
\end{equation}
Here \(K_\nu\) is the modified Bessel function, not the number of GT
directions. In particular,
\begin{equation}
\begin{aligned}
 M_1&=2(1+\mu),\\
 M_2&=4(\mu^2+3\mu+3),\\
 M_3&=8(\mu^3+6\mu^2+15\mu+15).
\end{aligned}
\label{eq:OQED-first-moments}
\end{equation}
For \(\mu>0\) its positive exponential moments exist precisely for
\(0<b\leq\mu^2\), with
\begin{equation}
 \int e^{b\tau}\rho_{\mu,\bb}(\dd\tau)
       =\exp\!\left(\mu-\sqrt{\mu^2-b}\right).
\label{eq:OQED-exponential-moment}
\end{equation}
There is no positive exponential moment when \(\mu=0\).

For $F_{a,M}$ of \eqref{eq:OQED-normalized-kernel} and every
integer $n\geq0$,
\begin{equation}
 \partial_a^nF_{a,M}(u)=(-h_M(u))^nF_{a,M}(u),\qquad
 h_M(u)=\sqrt{u+M^2}-M.
 \label{eq:OQED-depth-derivatives}
\end{equation}
For $a\in[a_-,a_+]$, $0<a_-\leq a_+$, and $0\leq M\leq M_+$,
\begin{equation}
 |\partial_a^nF_{a,M}(q^2)|
 \leq e^{a_+M_+}|q|^n e^{-a_-|q|}.
 \label{eq:OQED-depth-uniform-envelope}
\end{equation}
In particular, such derivatives preserve an established complete
graph bound when the additional polynomial numerator degree and
infrared factors are controlled. For $u>0$, $\partial_MF_{a,M}(u)>0$, with the right derivative at
$M=0$.

Define a Fourier-normalized one-line comparison for $d\geq0$:
\begin{equation}
 \mathscr Q_d(a,M,m)
 :=\int_{\RR^4}\frac{\dd^4q_{\bb}}{(2\pi)^4}
   \frac{|q|^dF_{a,M}(q^2)}{q^2+m^2},
 \quad m\geq0.
 \label{eq:OQED-one-line-depth}
\end{equation}
For every fixed $m,M\geq0$, it is finite at $a>0$, and
\begin{equation}
 \lim_{a\downarrow0}a^{d+2}\mathscr Q_d(a,M,m)
 =\frac{\Gamma(d+2)}{8\pi^2}.
 \label{eq:OQED-zero-depth-one-line}
\end{equation}
The convergence is uniform for $(m,M)$ in bounded nonnegative sets.
For fixed $m>0$, the two different strong-depth limits are
\begin{equation}
 \begin{aligned}
 \lim_{a\to\infty}a^{d+4}\mathscr Q_d(a,0,m)
   &=\frac{\Gamma(d+4)}{8\pi^2m^2},\\
 \lim_{a\to\infty}a^{(d+4)/2}\mathscr Q_d(a,M,m)
   &=\frac{(2M)^{(d+4)/2}\Gamma((d+4)/2)}
           {16\pi^2m^2},\quad M>0.
 \end{aligned}
 \label{eq:OQED-strong-depth-one-line}
\end{equation}
These asymptotics hold in their stated regimes, not uniformly over
arbitrary joint limits of $a$ and $M$.

For $a>0$, $M,m\geq0$, $d\geq0$ and $R>0$, the
Fourier-normalized line integral of
\eqref{eq:OQED-one-line-depth} obeys
\begin{equation}
 \begin{aligned}
 &\int_{|q|>R}\frac{\dd^4q_{\bb}}{(2\pi)^4}
     \frac{|q|^dF_{a,M}(q^2)}{q^2+m^2}\\
 &\qquad\leq \frac{e^{aM}}{8\pi^2a^{d+2}}
                     \Gamma(d+2,aR),
 \end{aligned}
 \label{eq:OQED-exponential-line-tail}
\end{equation}
where $\Gamma(s,x)=\int_x^\infty
 t^{s-1}e^{-t}\dd t$ is the upper incomplete gamma
function. For each fixed positive depth the right side is
exponentially small as $R\to\infty$. Selected-line graph tails
inherit finite products and union bounds only when the
\emph{complete} anisotropic numerator and unselected-line
estimate in Theorem~\ref{thm:optimized-selected-lines}
has been verified. These are Euclidean coefficient bounds,
not contour-arc or physical-cut estimates.

Fix $m>0$, $M\geq0$, and real Euclidean $P$. Put
$H_{M,P}(q):=h_M(q^2)+h_M((q+P)^2)$. For each $a>0$,
$a\mapsto B_{a,M,m}(P)$ is completely monotone:
\begin{equation}
 \begin{aligned}
 &(-1)^n\partial_a^n B_{a,M,m}(P)\\
 &\quad=\int\frac{\dd^4q_{\bb}}{(2\pi)^4}
 \frac{H_{M,P}(q)^n e^{-aH_{M,P}(q)}}
 {(q^2+m^2)((q+P)^2+m^2)}>0
 \end{aligned}
 \label{eq:OQED-bubble-depth-derivatives}
\end{equation}
for every integer $n\geq0$. For $a\geq a_->0$,
$0\leq M\leq M_+$, and any real $P$,
\begin{equation}
 |\partial_a^nB_{a,M,m}(P)|\leq
 c_{n,a_-}B_{a_-/2,M_+,m}(0),
 \label{eq:OQED-bubble-depth-uniform}
\end{equation}
where $c_{0,a_-}=1$ and
$c_{n,a_-}=(2n/(\mathrm e\,a_-))^n$ for $n\geq1$.
The bubble is holomorphic in the \emph{depth} $a$ on
$\Re a>0$ at fixed real $P$. For fixed $a>0$ it is
nondecreasing in the auxiliary mass $M$ (strictly for
$P$ in the stated real domain). None of these statements
implies analyticity in complex external momentum when $M=0$,
or reflection positivity of a physical two-point function.

Fix $m>0$ and $d\geq0$, and consider $M=\mu/a$ with fixed
$\mu\geq0$ as $a\to\infty$. Define
\begin{equation}
 \mathcal H_d(\mu):=\int_0^\infty v^{d+3}
                  e^{-\sqrt{v^2+\mu^2}+\mu}\dd v.
 \label{eq:OQED-crossover-H}
\end{equation}
Then, uniformly for $\mu$ in compact subsets of $[0,\infty)$,
\begin{equation}
 \begin{aligned}
 \lim_{a\to\infty}a^{d+4}\mathscr Q_d(a,\mu/a,m)
    &=\frac{\mathcal H_d(\mu)}{8\pi^2m^2},\\
 \lim_{a\to\infty}a^4B_{a,\mu/a,m}(0)
    &=\frac{3+6\mu+4\mu^2}{64\pi^2m^4}.
 \end{aligned}
 \label{eq:OQED-strong-depth-crossover}
\end{equation}
Here $B_{a,M,m}$ is the literal real Euclidean comparison
\eqref{eq:OQED-literal-depth-bubble}. Furthermore $\mathcal H_0(\mu)=6+6\mu+2\mu^2$,
$\mathcal H_d(0)=\Gamma(d+4)$, and
\begin{equation}
 \mathcal H_d(\mu)\sim\tfrac12(2\mu)^{(d+4)/2}
          \Gamma((d+4)/2)\qquad(\mu\to\infty).
 \label{eq:OQED-large-mu-crossover}
\end{equation}
The last limit concerns the crossover coefficient; it is not a
uniform joint $a,M$ asymptotic over unbounded $aM$.

Retain \(S_{a,M}=F_{a,M}S_0\), \(a>0\), \(m_e>0\),
\(M\geq0\), and \(e\ne0\), but no longer assume diagonal
continuity. Fix real \(P\ne0\), let \(k'=k+P\), and require both
vertices of the two-vertex bubble to satisfy
\(P\cdot\Gamma=S_{a,M}^{-1}(k')-S_{a,M}^{-1}(k)\) in its common
external orientation. Define its complete two-vertex coefficient by
\[
 \begin{aligned}
 I_W^{\mu\nu}(k,P):=-e^2\Tr\bigl[&\Gamma^\mu(k',k)S_{a,M}(k)\\
                    &\Gamma^\nu(k,k')S_{a,M}(k')\bigr].
 \end{aligned}
\]
This graph is not componentwise absolutely integrable. Specifically,
\begin{equation}
\begin{aligned}
 P_\mu P_\nu I_W^{\mu\nu}(k,P)
 =-e^2\Tr\bigl[&S_{a,M}^{-1}(k')S_{a,M}(k)\\
               &+S_{a,M}^{-1}(k)S_{a,M}(k')-2\one\bigr],
\end{aligned}
\label{eq:OQED-double-Ward-contraction}
\end{equation}
and along \(k=rn\), \(|n|=1\), \(r\to\infty\),
\begin{equation}
 P_\mu P_\nu I_W^{\mu\nu}(rn,P)
       \longrightarrow-8e^2\bigl[\cosh(a n\cdot P)-1\bigr].
\label{eq:OQED-fixed-transfer-obstruction}
\end{equation}

In this constant-background realization the combined coefficient is
\begin{equation}
\begin{aligned}
 J_{\rm cb}^{\mu\nu}(k)
 &=e^2\Tr[\mathcal D_{,\mu\nu}S
           -\mathcal D_{,\mu}S\mathcal D_{,\nu}S]\\
 &=e^2\partial_\mu\partial_\nu\log\det\mathcal D(k).
\end{aligned}
\label{eq:OQED-contact-Hessian}
\end{equation}
It has the exact tensor form, with \(u=k^2\), \(\Omega=\sqrt{u+M^2}\),
\begin{equation}
\begin{split}
 \frac{J_{\rm cb}^{\mu\nu}}{e^2}
 =4a\left(\frac{\delta^{\mu\nu}}{\Omega}
               -\frac{k^\mu k^\nu}{\Omega^3}\right)
   +\frac{4\delta^{\mu\nu}}{u+m_e^2}
               -\frac{8k^\mu k^\nu}{(u+m_e^2)^2}.
\end{split}
\label{eq:OQED-contact-explicit}
\end{equation}
The leading constant of the two-vertex term cancels, but the summed
tensor is still not componentwise absolutely integrable. In fact,
\begin{equation}
\begin{split}
 \sum_\mu J_{\rm cb}^{\mu\mu}(k)
 =e^2\left[
 \frac{4a(3u+4M^2)}{(u+M^2)^{3/2}}
       +\frac{8(u+2m_e^2)}{(u+m_e^2)^2}\right]>0,
\end{split}
\label{eq:OQED-contact-trace}
\end{equation}
and its radial exhaustion is exactly
\begin{equation}
 \int_{|k|<R}\frac{\dd^4k_{\bb}}{(2\pi)^4}
            \sum_\mu J_{\rm cb}^{\mu\mu}(k)
  =\frac{e^2}{2\pi^2}\left[
        \frac{aR^4}{\sqrt{R^2+M^2}}+\frac{R^4}{R^2+m_e^2}\right].
\label{eq:OQED-contact-exhaustion}
\end{equation}

For \(a,M,m>0\), let
\(C(q)=F_{a,M}(q^2)/(q^2+m^2)\), with the principal square-root branch, and set
\[
 \mathcal T_*=\{P\in\CC^4:|\Im P|<2m_*\},\qquad
 m_*:=\min\{m,M\}.
\]
The literal scalar comparison bubble has the holomorphic continuation
\begin{equation}
 B(P)=\int_{\RR^4}\frac{\dd^4k_{\bb}}{(2\pi)^4}
                     C(k-P/2)C(k+P/2),\qquad P\in\mathcal T_*.
\label{eq:OQED-bubble-tube}
\end{equation}
For every \(0\leq d<2m_*\), its integrand obeys the common bound
\begin{equation}
 |C(k-P/2)C(k+P/2)|
 \leq\frac{e^{2aM}e^{-2a|k|}}{(m^2-d^2/4)^2},
 \qquad |\Im P|\leq d.
\label{eq:OQED-bubble-tube-majorant}
\end{equation}
Near zero write \(B(P)=b(P^2)\), with \(P^2=\sum_\mu P_\mu^2\).
Then \(b(w)\) is holomorphic for \(|w|<4m_*^2\). For
\(0<r<\mathcal R<4m_*^2\), its Taylor coefficients \(b_n\) satisfy
\begin{equation}
\begin{aligned}
 |b_n|&\leq B_{\mathcal R}\mathcal R^{-n},\\
 \sup_{|w|\leq r}\left|b(w)-\sum_{n=0}^N b_n w^n\right|
   &\leq B_{\mathcal R}
          \frac{(r/\mathcal R)^{N+1}}{1-r/\mathcal R},\\
 B_{\mathcal R}&:=\frac{3e^{2aM}}
           {64\pi^2a^4(m^2-\mathcal R/4)^2}.
\end{aligned}
\label{eq:OQED-bubble-Taylor-bound}
\end{equation}

For the scalar comparison with \(a,M,m>0\), let \(w=P_E^2\)
on the real Euclidean axis. The invariant function \(b(w)\)
admits a finite positive Laplace measure \(\nu_{\bb}\) on
\((0,\infty)\), with representation
\begin{equation}
 \begin{aligned}
  b(w)&=\int_0^\infty e^{-\lambda w}\nu_{\bb}(\dd\lambda),
       \qquad w\geq0,\\
  \int_0^\infty e^{s\lambda}\nu_{\bb}(\dd\lambda)&<\infty,
       \qquad 0<s<4m_*^2.
 \end{aligned}
 \label{eq:OQED-scalar-positive-measure}
\end{equation}
Thus \(b\) is holomorphic for \(\Re w>-4m_*^2\) and, on the
real half-line, \((-1)^n b^{(n)}(w)>0\) for every \(n\geq0\).
Its coefficients \(b_n=b^{(n)}(0)/n!\) alternate in sign. Every
finite truncation \(p_N(w)=\sum_{n=0}^N b_nw^n\) satisfies
\begin{equation}
 0\leq(-1)^{N+1}[b(w)-p_N(w)]
       \leq |b_{N+1}|w^{N+1},\qquad w\geq0.
 \label{eq:OQED-scalar-signed-enclosure}
\end{equation}
In particular, odd truncations are lower bounds and even truncations
are upper bounds on the positive Euclidean invariant axis.

Fix $m>0$ and $M\geq0$. For real Euclidean $P$, $w=P^2\geq0$,
define $C_{a,M,m}(q):=F_{a,M}(q^2)/(q^2+m^2)$ and
\begin{equation}
 D_{a,M,m}(w):=B_{a,M,m}(0)-B_{a,M,m}(P).
 \label{eq:OQED-subtracted-bubble-def}
\end{equation}
At every $a>0$ this is an absolutely convergent \emph{common}
integral and satisfies
\begin{equation}
 0\leq D_{a,M,m}(w)\leq\frac{w}{64\pi^2m^2}.
 \label{eq:OQED-subtraction-uniform-bound}
\end{equation}
As $a\downarrow0$ with $M$ fixed,
\begin{equation}
 \boxed{\displaystyle
 \lim_{a\downarrow0}D_{a,M,m}(w)
   =\frac1{16\pi^2}\int_0^1
      \log\left(1+\frac{x(1-x)w}{m^2}\right)\dd x.}
 \label{eq:OQED-subtraction-limit}
\end{equation}
Convergence is uniform when $w$ and $M$ range over compact
subsets of $[0,\infty)$ and $m$ ranges over a compact subset of
$(0,\infty)$. In addition,
\begin{equation}
 \lim_{a\downarrow0}D_{a,M,m}'(0)
  =\frac1{96\pi^2m^2}.
 \label{eq:OQED-subtraction-slope-limit}
\end{equation}
In contrast, the \emph{unsubtracted} comparison has the
universal finite-part asymptotic
\begin{equation}
 B_{a,M,m}(0)=\frac1{8\pi^2}
  \left[\log\frac1{2am}-\gamma_{\mathrm E}-\frac12\right]
  +o(1),\quad a\downarrow0,
 \label{eq:OQED-unsubtracted-log-depth}
\end{equation}
where $\gamma_{\mathrm E}$ is Euler's constant. In this
normalization the constant inside the logarithm is specified,
not absorbed into an arbitrary reference momentum scale.
The comparison makes no assertion about a jointly completed
O--QED kernel-off gauge functional or about uniform Lorentzian
boundary values.

On a finite-dimensional retained RT space, define the full pencils
\(K_X=K_0+\delta K_X\) and \(K_Y=K_0+\delta K_Y\).
Suppose both are holomorphic on a neighbourhood of the closed disk
\(\overline{\mathbb D}(z_Y,r)\), \(r>0\), and that
\(\det K_Y\) has exactly one zero there, the simple zero at \(z_Y\),
with no zero on the boundary. Assume a certified bound
\(\|K_X(z)-K_Y(z)\|\leq E_K(z)\) on that boundary and
\begin{equation}
 \sup_{|z-z_Y|=r}\|K_Y(z)^{-1}\|E_K(z)<1.
 \label{eq:OQED-finite-pole-contour-test}
\end{equation}
Then \(\det K_X\) has exactly one zero in the disk, also simple,
and its location \(z_X\) satisfies \(|z_X-z_Y|<r\).
For \(Z\in\{X,Y\}\), use these enclosed endpoint roots to define
the rate-comparison quantities relative to one fixed \(z_*\):
\begin{equation}
\begin{aligned}
 \Gamma_Z^{\rm fin}&:=-2\Im(z_Z-z_*),\\
 |\Gamma_X^{\rm fin}-\Gamma_Y^{\rm fin}|&<2r.
\end{aligned}
 \label{eq:OQED-finite-pole-rate-enclosure}
\end{equation}
Thus \(\Gamma_Y^{\rm fin}\geq2r\) certifies a strictly positive
\(\Gamma_X^{\rm fin}\). Identifying this enclosed root with the
selected baseline mode additionally requires the contour condition
below.

On the same finite retained matrix space, let \(K_0\) and \(\delta K\)
be holomorphic near \(\overline{\mathbb D}(z_*,R_{\rm p})\),
with \(R_{\rm p}>0\).
Suppose \(\det K_0\) has precisely one zero in this disk, the simple
zero \(z_*\), and none on its boundary \(\Gamma_*\). Assume a
certified constant \(0<\vartheta_{\rm p}<1\) satisfies
\begin{equation}
 \sup_{z\in\Gamma_*}\norm{K_0(z)^{-1}\delta K(z)}
                    \leq\vartheta_{\rm p}.
 \label{eq:OQED-complex-pole-margin}
\end{equation}
The pole family \(K_{\lambda_{\rm p}}=K_0+\lambda_{\rm p}\delta K\)
has one simple interior root \(z(\lambda_{\rm p})\), holomorphic for
\(|\lambda_{\rm p}|<\vartheta_{\rm p}^{-1}\), with
\(z(0)=z_*\). Writing \(z(\lambda_{\rm p})-z_*
=\sum_{n\geq1}c_n\lambda_{\rm p}^n\), one has
\begin{equation}
 \begin{aligned}
  |c_n|&\leq R_{\rm p}\vartheta_{\rm p}^{\,n},\\
  \left|z(1)-z_*-\sum_{n=1}^{N}c_n\right|
     &\leq\frac{R_{\rm p}\vartheta_{\rm p}^{\,N+1}}
                    {1-\vartheta_{\rm p}},\\
  |\Gamma^{\rm fin}-\Gamma^{(1)}|
     &\leq\frac{2R_{\rm p}\vartheta_{\rm p}^{\,2}}
                    {1-\vartheta_{\rm p}}.
 \end{aligned}
 \label{eq:OQED-pole-remainder-certificate}
\end{equation}
Here \(N\geq1\), \(c_1=\dot z\), and the rates use the same
baseline and pole bookkeeping parameter as
\eqref{eq:OQED-pole-bookkeeping-family}. The radius and margin are
certification data, not additional theory parameters.
